#include <iostream>

// Pass-by-value: modifies only a local copy
void modifyByValue(int x) {
    x += 100;
}

// Pass-by-reference (C++ style): directly modifies the original variable
void modifyByReference(int& x) {
    x += 100;
}

int main() {
    int original = 42;

    modifyByValue(original);
    std::cout << "After modifyByValue: " << original << "\n";

    modifyByReference(original);
    std::cout << "After modifyByReference: " << original << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

// Demonstrating scaling and shifting logic: face = 1 + (rawVal % 6)
int scaleAndShift(int rawVal) {
    return 1 + (rawVal % 6);
}

int main() {
    // Representative deterministic sequence simulating 18 pseudo-random outputs
    const int rawValues[18] = {
        5, 5, 4, 4, 5,
        4, 0, 0, 4, 2,
        5, 5, 1, 3, 1,
        5, 1, 2
    };

    int freq[7] = {0}; // 1-indexed counters for faces 1..6

    for (int i = 0; i < 18; ++i) {
        int face = scaleAndShift(rawValues[i]);
        switch (face) {
            case 1: ++freq[1]; break;
            case 2: ++freq[2]; break;
            case 3: ++freq[3]; break;
            case 4: ++freq[4]; break;
            case 5: ++freq[5]; break;
            case 6: ++freq[6]; break;
        }
    }

    std::cout << std::setw(6) << "Face" << std::setw(12) << "Frequency" << "\n";
    for (int face = 1; face <= 6; ++face) {
        std::cout << std::setw(6) << face << std::setw(12) << freq[face] << "\n";
    }

    return 0;
}
